/**
 * robots.txt for nooni.dk — generated by Next.js at build time.
 *
 * Allow every crawler, AI ones included. A small
 * shop wants to be found and quoted everywhere, and ChatGPT or Claude
 * can only recommend Nooni if they're allowed to read the site.
 * /llms.txt gives those assistants a plain-text summary of the shop.
 *
 * If you want to hide the site again (e.g. during a future redesign),
 * change `allow: "/"` to `disallow: "/"`.
 *
 * Docs: https://nextjs.org/docs/app/api-reference/file-conventions/metadata/robots
 */

import type { MetadataRoute } from "next";

/**
 * AI crawlers named one by one. They are already allowed by `*`, but
 * an explicit group per bot is unambiguous, and some site audits and
 * bots read a named group as a clear "yes, you may use this".
 */
const AI_CRAWLERS = [
  "GPTBot",
  "OAI-SearchBot",
  "ChatGPT-User",
  "ClaudeBot",
  "Claude-SearchBot",
  "Claude-User",
  "PerplexityBot",
  "Perplexity-User",
  "Google-Extended",
  "Applebot-Extended",
];

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      { userAgent: "*", allow: "/" },
      ...AI_CRAWLERS.map((userAgent) => ({ userAgent, allow: "/" })),
    ],
    sitemap: "https://nooni.dk/sitemap.xml",
  };
}
